import csv
import io
import re
from typing import List, Dict, Any


_EXPECTED_WIDTH = 9
_EXPECTED_HEADERS = [
    "date",
    "time",
    "qty",
    "productid",
    "price",
    "producttype",
    "productdescription",
    "url",
    "comments",
]


def _normalize_header(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.lstrip("\ufeff").lower())


def _header_score(row: List[str]) -> float:
    if not row:
        return float("-inf")

    normalized = [_normalize_header(value) for value in row]
    score = -abs(len(row) - _EXPECTED_WIDTH) * 8.0

    expected_set = set(_EXPECTED_HEADERS)
    for index, value in enumerate(normalized):
        if index < len(_EXPECTED_HEADERS) and value == _EXPECTED_HEADERS[index]:
            score += 12.0
        elif value in expected_set:
            score += 3.0

    if len(row) == _EXPECTED_WIDTH:
        score += 5.0
    if all(value != "" for value in normalized):
        score += 1.0

    return score


def _field_score(header: str, value: str) -> float:
    name = _normalize_header(header)
    stripped = value.strip()

    if name == "date":
        if re.match(r"^\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}(?:\b|$)", stripped):
            return 8.0
        return -5.0

    if name == "time":
        if re.search(r"(?:^|\s)\d{1,2}:\d{2}(?::\d{2})?(?:\s*[APap][Mm])?(?:\b|$)", stripped):
            return 8.0
        return -4.0

    if name in ("qty", "quantity"):
        if re.match(r"^[+-]?\d+$", stripped):
            return 8.0
        return -6.0

    if name in ("productid", "productcode", "sku"):
        if re.match(r"^(?=.*[A-Za-z])(?=.*\d)[A-Za-z0-9_.:/-]+$", stripped):
            return 7.0
        return -4.0

    if name in ("price", "cost", "amount"):
        if re.match(r"^[\$£€¥]?\s*[+-]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)?$", stripped) and re.search(r"\d", stripped):
            return 8.0
        return -5.0

    if name in ("url", "uri", "link", "website"):
        if re.match(r"^(?:https?|ftp)://", stripped, re.IGNORECASE):
            return 10.0
        if stripped == "":
            return -2.0
        return -7.0

    if "description" in name:
        if stripped == "":
            return -1.0
        return 3.0 if len(stripped) >= 40 else 1.5

    if "type" in name or "name" in name or "title" in name:
        if stripped == "":
            return -1.0
        return 2.0 if len(stripped) <= 120 else 0.5

    if "comment" in name or "note" in name or "remark" in name:
        return 2.0 if stripped == "" else 0.5

    return 0.5 if stripped else 0.0


def _normalize_row(row: List[str], columns: List[str]) -> List[str]:
    width = len(columns)

    if len(row) == width:
        return row

    if len(row) < width:
        return row + [""] * (width - len(row))

    if width == 0:
        return []

    if len(row) > 200:
        if width == 1:
            return [",".join(row)]
        return row[:width - 1] + [",".join(row[width - 1:])]

    count = len(row)
    negative_infinity = float("-inf")
    states = [negative_infinity] * (count + 1)
    states[0] = 0.0
    paths: List[List[int]] = []

    for column_index, column in enumerate(columns):
        next_states = [negative_infinity] * (count + 1)
        choices = [-1] * (count + 1)
        remaining_columns = width - column_index - 1

        for consumed in range(count + 1):
            current_score = states[consumed]
            if current_score == negative_infinity:
                continue

            max_take = count - consumed - remaining_columns
            if max_take < 1:
                continue

            for take in range(1, max_take + 1):
                end = consumed + take
                combined = ",".join(row[consumed:end])
                score = current_score + _field_score(column, combined)
                score -= 1.25 * (take - 1)

                if score > next_states[end]:
                    next_states[end] = score
                    choices[end] = consumed

        states = next_states
        paths.append(choices)

    if states[count] == negative_infinity:
        return row[:width - 1] + [",".join(row[width - 1:])]

    result = [""] * width
    end = count

    for column_index in range(width - 1, -1, -1):
        start = paths[column_index][end]
        if start < 0:
            return row[:width - 1] + [",".join(row[width - 1:])]
        result[column_index] = ",".join(row[start:end])
        end = start

    return result


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    if not isinstance(raw_csv, str) or raw_csv == "":
        return {"columns": [], "rows": []}

    try:
        csv.field_size_limit(2147483647)
    except (OverflowError, ValueError):
        pass

    stream = io.StringIO(raw_csv, newline="")
    reader = csv.reader(
        stream,
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    parsed_rows: List[List[str]] = []
    try:
        for row in reader:
            parsed_rows.append([str(value) for value in row])
    except csv.Error:
        return {"columns": [], "rows": []}

    if not parsed_rows:
        return {"columns": [], "rows": []}

    best_index = 0
    best_score = float("-inf")

    for index, row in enumerate(parsed_rows):
        score = _header_score(row)
        if score > best_score:
            best_score = score
            best_index = index

    columns = list(parsed_rows[best_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")
    columns = [column.strip() for column in columns]

    if len(columns) < _EXPECTED_WIDTH:
        columns.extend(
            "column_" + str(index + 1)
            for index in range(len(columns), _EXPECTED_WIDTH)
        )
    elif len(columns) > _EXPECTED_WIDTH:
        columns = columns[:_EXPECTED_WIDTH - 1] + [
            ",".join(columns[_EXPECTED_WIDTH - 1:])
        ]

    output_rows: List[List[str]] = []
    for row in parsed_rows[best_index + 1:]:
        if len(row) == 0:
            continue
        output_rows.append(_normalize_row(row, columns))

    return {"columns": columns, "rows": output_rows}
